function updateTable(){const name=state.dataset,rows=filteredRows(name),columns=rows.length?Object.keys(rows[0]):Object.keys((tables[name]||[])[0]||{});$('#table-count').textContent=`${rows.length} registros${['recurrence','periods','unique2025','trend'].includes(name)?' · referência completa, sem filtros':' · filtros aplicados'}`;$('#data-table').innerHTML=`<thead><tr>${columns.map(c=>`<th scope="col">${esc(c.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,180).map(r=>'<tr>'+columns.map(c=>`<td>${r[c]===null?'—':typeof r[c]==='number'?Number.isInteger(r[c])?r[c]:fmt(r[c],6):esc(r[c])}</td>`).join('')+'</tr>').join('')||`<tr><td colspan="${columns.length}">Nenhum registro corresponde à seleção.</td></tr>`}</tbody>`;if(rows.length>180)$('#table-count').textContent+=' · mostrando os 180 primeiros; download inclui todos';}
function downloadCSV(name){const rows=filteredRows(name);if(!rows.length){$('#status').textContent='Nenhum registro para exportar nesta seleção.';return;}const columns=Object.keys(rows[0]),q=x=>x===null?'':`"${String(x).replaceAll('"','""')}"`;const csv='\ufeff'+columns.map(q).join(';')+'\r\n'+rows.map(r=>columns.map(c=>q(typeof r[c]==='number'?String(r[c]).replace('.',','):r[c])).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`Lavras_${name}_${state.start}_${state.end}_${state.month===0?'todos_meses':state.month===13?'ago_out':MONTHS[state.month-1]}_${state.classCode??'todas_classes'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function getSummary(){return {periodo:[state.start,state.end],mes:monthLabel(),classe:state.classCode,area_soma_anual_ha:lastStats?.sum,area_unica_ha:lastStats?.unique,area_recorrente_ha:lastStats?.recurrent,percentual_municipio:lastStats?lastStats.unique/grid.area_municipio_ha*100:null,unidade:'hectares',fonte:'MapBiomas Fogo C5; Cobertura C11',view:state.view};}
function installTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});const tools=[{name:'consultar_selecao_fogo_lavras',description:'Consulta as areas de fogo e os filtros ativos do estudo de Lavras, sem alterar a pagina.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>getSummary()},{name:'filtrar_fogo_lavras',description:'Aplica filtros de periodo, mes e codigo de cobertura aos mapas e graficos visiveis do estudo. Mes 0 significa todos, 13 significa agosto a outubro.',inputSchema:{type:'object',properties:{start:{type:'integer',minimum:2011,maximum:2025},end:{type:'integer',minimum:2011,maximum:2025},month:{type:'integer',minimum:0,maximum:13},classCode:{type:['integer','null']}},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['start','end','month','classCode'].includes(k)))throw Error('Filtros inválidos.');return setFilters(input);}}];for(const t of tools){try{Promise.resolve(context.registerTool(t,{signal:controller.signal})).catch(()=>{});}catch{}}}
function setupEvents(){for(let y=2011;y<=2025;y++){for(const id of ['start','end','map-year'])$('#'+id).add(new Option(String(y),String(y)));}MONTHS.forEach((m,i)=>$('#month').add(new Option(m,String(i+1))));$('#month').add(new Option('Agosto a outubro','13'));tables.legend.forEach(r=>$('#class').add(new Option(r.classe,String(r.codigo_original))));syncControls();
 $('#start').onchange=e=>{const y=Number(e.target.value);setFilters({start:y,end:Math.max(y,state.end)});};$('#end').onchange=e=>{const y=Number(e.target.value);setFilters({end:y,start:Math.min(y,state.start)});};$('#month').onchange=e=>setFilters({month:Number(e.target.value)});$('#class').onchange=e=>setFilters({classCode:e.target.value==='all'?null:Number(e.target.value)});$('#reset').onclick=()=>setFilters({start:2011,end:2025,month:0,classCode:null});$$('[data-period]').forEach(b=>b.onclick=()=>{const [start,end]=b.dataset.period.split(',').map(Number);setFilters({start,end});});$$('.nav').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-show-map]').forEach(b=>b.onclick=()=>{state.layer=b.dataset.showMap;syncControls();showView('overview');});
 $('#map-layer').onchange=e=>{state.layer=e.target.value;stopPlay();syncControls();drawRaster();};$('#map-year').onchange=e=>{state.mapYear=Number(e.target.value);if(state.mapYear<state.start||state.mapYear>state.end){setFilters({start:Math.min(state.start,state.mapYear),end:Math.max(state.end,state.mapYear)});}else drawRaster();};$('#play').onclick=()=>{if(playTimer)return stopPlay();$('#play').textContent='Pausar';$('#play').setAttribute('aria-pressed','true');playTimer=setInterval(()=>{state.mapYear=state.mapYear>=state.end?state.start:state.mapYear+1;$('#map-year').value=state.mapYear;drawRaster();},1500);};
 $('#coverage-measure').onchange=e=>{state.measure=e.target.value;updateCoverage();};$('#dry-season').onclick=()=>setFilters({month:13});$('#dataset').onchange=e=>{state.dataset=e.target.value;updateTable();};$('#download-table').onclick=()=>downloadCSV(state.dataset);$('#download-original').onclick=()=>{const a=document.createElement('a');a.href='data/'+state.dataset+'.csv';a.download='Lavras_'+state.dataset+'_validado.csv';a.click();};$('#export').onclick=()=>$('#download-dialog').showModal();$('#confirm-export').onclick=()=>{downloadCSV($('#export-dataset').value);$('#download-dialog').close();};
 chart('annual-chart').on('click',p=>setFilters({start:2011+p.dataIndex,end:2011+p.dataIndex}));chart('month-chart').on('click',p=>setFilters({month:p.dataIndex+1}));chart('heat-chart').on('click',p=>{const year=state.start+p.value[1];setFilters({start:year,end:year,month:p.value[0]+1});});
 window.addEventListener('resize',()=>{Object.values(charts).forEach(c=>c.resize());map?.invalidateSize();});}
function stopPlay(){clearInterval(playTimer);playTimer=null;$('#play').textContent='Reproduzir anos';$('#play').setAttribute('aria-pressed','false');}
async function init(){try{[grid,tables,limite,cells,areas,fire,cover]=await Promise.all([json('data/grid.json'),json('data/tables.json'),json('data/limite.geojson'),binary('cells',Uint32Array),binary('areas',Float64Array),binary('fire',Uint8Array),binary('cover',Uint8Array)]);if(cells.length!==grid.n||areas.length!==grid.n||fire.length!==grid.n*15||cover.length!==grid.n*15)throw Error('As dimensões dos dados espaciais não coincidem.');indexMap=new Int32Array(grid.width*grid.height);indexMap.fill(-1);cells.forEach((cell,i)=>indexMap[cell]=i);buildMap();setupEvents();$('#area-domain').textContent=fmt(grid.area_municipio_ha);const t=tables.trend[0];$('#trend-values').innerHTML=`<div><span>Mann–Kendall · p-valor</span><strong>${fmt(t.p_valor_bilateral,4)}</strong></div><div><span>Inclinação de Sen</span><strong>${fmt(t.inclinacao_sen_ha_ano)} <small>ha/ano</small></strong></div><div><span>IC 95% · ha/ano</span><strong>${fmt(t.ic95_inferior_ha_ano)} a ${fmt(t.ic95_superior_ha_ano)}</strong></div>`;$('#trend-explanation').textContent='Não foi detectada tendência persistente de aumento ou redução estatisticamente significativa na série anual completa, ao nível de 5%. O intervalo de confiança da inclinação de Sen inclui zero.';initialized=true;update();installTools();window.LavrasStudy={getSummary,setFilters,showView,downloadCSV};}catch(e){console.error(e);$('#status').textContent='Não foi possível carregar os dados.';const banner=document.createElement('div');banner.className='error-banner';banner.setAttribute('role','alert');banner.textContent=e.message+' Recarregue a página para tentar novamente.';$('#main').prepend(banner);}}
init();
